uniform float amzp_strength;
uniform float amzp_threshold;
uniform float amzp_intensity;
layout(color) uniform half4 amzp_tint;
uniform float amzp_colorR;
uniform float amzp_colorG;
uniform float amzp_colorB;
uniform float amzp_dispersion;
uniform float amzp_dispersionAngle;
uniform float amzp_halo;
uniform float amzp_blend;
uniform float amzp_alpha;

        const float3 luminanceWeighting = float3(0.2126, 0.7152, 0.0722);

        float4 composite(float4 a, float4 b) {
            return a * (1. - b.a) + b;
        }

        float4 blurInternal(float2 texOffset, float2 st, float numBlurPixelsPerSide)
        {
            if(amzp_strength <= 0.0)
                return float4(0,0,0,0);
            const float PI = 3.14159265;
            float adjSigma = numBlurPixelsPerSide / 2.14596602;

             float3 incrementalGaussian;
            incrementalGaussian.x = 1.0 / (sqrt(2.0 * PI) * adjSigma);
            incrementalGaussian.y = exp(-0.5 / (adjSigma * adjSigma));
            incrementalGaussian.z = incrementalGaussian.y * incrementalGaussian.y;

            float4 avgValue = float4(0.0);
             float coefficientSum = 0.0;

            avgValue += ((amzPass==1 ? amzTexture(1,st) : amzTexture(2,st)).rgba * incrementalGaussian.x);
            coefficientSum += incrementalGaussian.x;

            for (float i = 1.0; i <= numBlurPixelsPerSide; i += 2.0) {
                float offset0 = i;
                float offset1 = i + 1.0;
                incrementalGaussian.xy *= incrementalGaussian.yz;
                coefficientSum += (2.0 * incrementalGaussian.x);
                float weight0 = incrementalGaussian.x;
                incrementalGaussian.xy *= incrementalGaussian.yz;
                coefficientSum += (2.0 * incrementalGaussian.x);
                float weight1 = incrementalGaussian.x;
                float weightL = weight0 + weight1;
                float offsetL = (offset0*weight0 + offset1*weight1) / weightL;
                float2 stL = clamp(st - offsetL * texOffset, float2(0.0), float2(1.0));
                float2 stR = clamp(st + offsetL * texOffset, float2(0.0), float2(1.0));
                avgValue += ((amzPass==1 ? amzTexture(1,stL) : amzTexture(2,stL)) * weightL);
                avgValue += ((amzPass==1 ? amzTexture(1,stR) : amzTexture(2,stR)) * weightL);
            }
            return avgValue / coefficientSum;
        }

        void amzRender() {
            if (amzPass == 0) {

                float4 c = amzTexture(0, amzScreenNorm().st);
                float lum = dot(c.rgb, luminanceWeighting);
                float3 tintRGB = amzp_tint.rgb; 
                float3 colored = mix(c.rgb, tintRGB * c.a, amzp_blend);
                amzOutput = (lum > amzp_threshold) ? float4(colored, c.a) : float4(0.0);
            } else if (amzPass == 1) {
                float kernelSize = amzp_strength * 0.285 * length(screen.zw);
                float2 texOffset = float2(1.0/(screen.zw/2.0).x, 0.0);
                amzOutput = blurInternal(texOffset, amzScreenNorm().st, kernelSize);
            } else if (amzPass == 2) {
                float kernelSize = amzp_strength * 0.285 * length(screen.zw);
                float2 texOffset = float2(0.0, 1.0/(screen.zw/2.0).y);
                amzOutput = blurInternal(texOffset, amzScreenNorm().st, kernelSize);
            } else {

                float4 base = amzTexture(0, amzScreenNorm().st);
                float4 blurTex = amzTexture(3, amzScreenNorm().st);
                float blurAlpha = blurTex.a;


                float2 dir = float2(cos(amzp_dispersionAngle), sin(amzp_dispersionAngle));
                float2 offR = dir * amzp_dispersion * 0.5;
                float2 offG = -dir * amzp_dispersion * 0.25;
                float2 offB = dir * amzp_dispersion;


                float r = amzTexture(3, clamp(amzScreenNorm().st + offR, float2(0.0), float2(1.0))).r;
                float g = amzTexture(3, clamp(amzScreenNorm().st + offG, float2(0.0), float2(1.0))).g;
                float b = amzTexture(3, clamp(amzScreenNorm().st + offB, float2(0.0), float2(1.0))).b;

                float3 glowRGB = float3(r * amzp_colorR, g * amzp_colorG, b * amzp_colorB);
                glowRGB *= amzp_intensity;


                float hsq = 0.15;
                float h = (1. - smoothstep(0.0, hsq, abs(blurAlpha - hsq))) * amzp_halo;
                float3 haloRGB = mix(glowRGB/hsq * amzp_halo, amzp_tint.rgb * amzp_halo, amzp_blend) * h;
                glowRGB += haloRGB;


                float3 baseRGB = base.rgb / max(base.a, 0.0001);
                float3 outRGB = 1.0 - (1.0 - baseRGB) * (1.0 - glowRGB);
                float4 outColor = float4(outRGB, 1.0) * min(base.a, blurAlpha) * amzp_alpha;
                amzOutput = composite(base, outColor);
            }
        }

half4 main(float2 coord) { amzCoord=coord*2.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

